mapper.select:
SELECT cm.*, ci.cluster_name, CONCAT(c.service_name, ' - ', c.service_role) AS service_label FROM t_ddh_configuration_management cm LEFT JOIN t_ddh_cluster_info ci ON cm.cluster_id = ci.id LEFT JOIN t_ddh_cluster_existing_component c ON cm.existing_component_id = c.id WHERE 1=1
AND ( cm.config_name LIKE CONCAT('%', #{keyword}, '%') OR cm.config_file_name LIKE CONCAT('%', #{keyword}, '%') OR cm.description LIKE CONCAT('%', #{keyword}, '%') OR cm.current_value LIKE CONCAT('%', #{keyword}, '%') OR cm.platform_value LIKE CONCAT('%', #{keyword}, '%') )
AND cm.cluster_id = #{clusterId}
AND cm.config_status = #{configStatus}
ORDER BY cm.update_time DESC

SELECT *
FROM t_ddh_configuration_management
WHERE cluster_id = #{clusterId}
  AND service_name = #{serviceName}
ORDER BY config_file_name, config_name

SELECT *
FROM t_ddh_configuration_management
WHERE cluster_id = #{clusterId}
  AND service_name = #{serviceName}
  AND config_file_name = #{configFileName}
ORDER BY config_item_path

SELECT *
FROM t_ddh_configuration_management
WHERE cluster_id = #{clusterId}
  AND config_status = #{configStatus}
ORDER BY service_name, config_file_name

SELECT *
FROM t_ddh_configuration_management
WHERE cluster_id = #{clusterId}
  AND sync_status = #{syncStatus}
ORDER BY service_name, config_file_name
